{
  "name": "DL3000系列直流电子负载",
  "name_en": "DL3000 Series DC Electronic Load",
  "manufacturer": "Rigol",
  "description": "这是一款台式可编程直流电子负载，用于吸收被测电源提供的电流，并在恒流、恒压等模式下评估电源、适配器、电池和电源转换器的输出性能。设备支持电压、电流测量，以及远端感测和前面板锁定等实验室常用功能。",
  "description_en": "This is a benchtop programmable DC electronic load used to sink current from a device under test and evaluate the output performance of power supplies, adapters, batteries, and power converters in modes such as constant current and constant voltage. It supports voltage and current measurement, along with common lab features such as remote sensing and front-panel lock.",
  "tag_hints": [
    "DC electronic load",
    "power supply testing",
    "battery discharge testing",
    "constant current mode",
    "constant voltage mode",
    "remote sensing",
    "benchtop test instrument"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电子负载。",
      "description_en": "Initialize the electronic load."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁前面板按键。",
      "description_en": "Lock or unlock the front panel controls."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量负载电流。",
      "description_en": "Measure the load current."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量负载端电压。",
      "description_en": "Measure the voltage at the load terminals."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "启用或禁用远端感测。",
      "description_en": "Enable or disable remote sensing."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置负载吸收电流值。",
      "description_en": "Set the current draw setpoint."
    },
    {
      "action_name": "auto-set_cv_voltage",
      "description": "设置恒压模式的电压设定值。",
      "description_en": "Set the voltage setpoint for constant-voltage mode."
    },
    {
      "action_name": "auto-set_mode_current",
      "description": "切换到恒流模式。",
      "description_en": "Switch to constant-current mode."
    },
    {
      "action_name": "auto-set_mode_voltage",
      "description": "切换到恒压模式。",
      "description_en": "Switch to constant-voltage mode."
    },
    {
      "action_name": "auto-set_range",
      "description": "设置电流量程（高量程或低量程）。",
      "description_en": "Set the current range (high or low)."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "开启或关闭负载吸收。",
      "description_en": "Enable or disable the load input."
    }
  ]
}

